                id = o.str("id"),
                code = o.str("code"),
                claimUrl = o.str("claimUrl"),
                name = o.str("name"),
                programId = o.str("programId"),
                programName = o.str("programName"),
                type = o.str("type"),
                currency = o.str("currency"),
                valueMinor = o.longOrNull("valueMinor"),
                usage = o.str("usage"),
                usageLimit = o.intOrNull("usageLimit"),
                capacity = o.int("capacity"),
                perPerson = o.int("perPerson"),
                offerText = o.strOrNull("offerText"),
                percent = o.intOrNull("percent"),
                validUntil = o.strOrNull("validUntil"),
                status = o.str("status"),
                createdAt = o.str("createdAt"),
                closedAt = o.strOrNull("closedAt"),
                cards = o.req("cards") { x, y -> CloseBatchDataCards.read(x, y) },
                locationIds = o.opt("locationIds") { x, y -> Wire.list(x, y) { v1, p1 -> Wire.string(v1, p1) } },
                branchNames = o.req("branchNames") { x, y -> Wire.list(x, y) { v1, p1 -> Wire.string(v1, p1) } },
                spentMinor = o.double("spentMinor"),
                outstandingMinor = o.double("outstandingMinor"),
                onlineValue = o.opt("onlineValue") { x, y -> CloseBatchDataOnlineValue.read(x, y) },
            ).also { it.adopt(o.rest()) }
        }
    }
}

